-- =========================================================
-- SQL Schema สำหรับโปรเจกต์ "พบด่าน" (PhobDan) บน Supabase
-- สามารถคัดลอกโค้ดทั้งหมดนี้ไปวางใน Supabase Dashboard -> SQL Editor แล้วกด RUN
-- =========================================================

-- 1. สร้างตารางเก็บข้อมูลด่าน (checkpoints)
CREATE TABLE IF NOT EXISTS checkpoints (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    location_name TEXT NOT NULL,
    lat DOUBLE PRECISION NOT NULL,
    lng DOUBLE PRECISION NOT NULL,
    category TEXT NOT NULL, -- traffic_discipline, alcohol, speed, smoke, security
    direction TEXT NOT NULL, -- inbound, outbound, both, roadside
    direction_text TEXT NOT NULL,
    note TEXT,
    reported_timestamp BIGINT NOT NULL,
    reported_by TEXT DEFAULT 'สมาชิกชุมชน',
    upvotes INTEGER DEFAULT 1,
    downvotes INTEGER DEFAULT 0,
    status TEXT DEFAULT 'active', -- active, unverified, cleared
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. เปิดใช้งาน Row Level Security (RLS) และอนุญาตให้ทุกคนอ่าน/เพิ่มข้อมูลได้ (Public Community)
ALTER TABLE checkpoints ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public read access" 
ON checkpoints FOR SELECT 
USING (true);

CREATE POLICY "Allow public insert" 
ON checkpoints FOR INSERT 
WITH CHECK (true);

CREATE POLICY "Allow public update votes" 
ON checkpoints FOR UPDATE 
USING (true);

-- 3. เปิดระบบ Realtime (เพื่อให้หมุดเด้งขึ้นหน้าจอทุกคนทันทีที่มีคนปัก)
ALTER PUBLICATION supabase_realtime ADD TABLE checkpoints;

